using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Runtime.Serialization.Json;
using System.Threading;
using System.Windows.Forms;

namespace Frociart.Tests {
static class ClipboardShortcutTests {
    static int checks;static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;
    [DllImport("user32.dll")]static extern uint GetClipboardSequenceNumber();
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;Console.WriteLine("PASS "+message);}
    static T Field<T>(object o,string name){return(T)o.GetType().GetField(name,F).GetValue(o);}
    static object Call(object o,string name,params object[] args){return o.GetType().GetMethods(F).First(m=>m.Name==name&&m.GetParameters().Length==args.Length).Invoke(o,args);}
    static bool Key(Form form,Keys key){var args=new object[]{Message.Create(form.Handle,0x100,(IntPtr)(key&Keys.KeyCode),IntPtr.Zero),key};return(bool)form.GetType().GetMethod("ProcessCmdKey",F).Invoke(form,args);}
    static void Pump(int ms=40){var w=Stopwatch.StartNew();do{Application.DoEvents();Thread.Sleep(2);}while(w.ElapsedMilliseconds<ms);}
    static string Json(Diagram d){using(var s=new MemoryStream()){new DataContractJsonSerializer(typeof(Diagram)).WriteObject(s,d);return Convert.ToBase64String(s.ToArray());}}
    static int UndoCount(MainForm f){return Field<System.Collections.ICollection>(f,"undo").Count;}
    static void Bad(byte[] bytes,string message){bool rejected=false;try{FlowClipboard.Decode(bytes);}catch(InvalidDataException){rejected=true;}Check(rejected,message);}
    static void Shot(Control c,string name){Pump(15);string root=Environment.GetEnvironmentVariable("REVIEW_OUTPUT");Directory.CreateDirectory(root);using(var b=new Bitmap(c.Width,c.Height)){c.DrawToBitmap(b,c.ClientRectangle);b.Save(Path.Combine(root,name+".png"));}}
    static int ReleaseProbe(string exe,string source,string mode){
        string probe=Environment.GetEnvironmentVariable("CLIPBOARD_RELEASE_PROBE");
        var start=new ProcessStartInfo(probe,"\""+Path.GetFullPath(exe)+"\" \""+Path.GetFullPath(source)+"\" "+mode){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,RedirectStandardOutput=true,RedirectStandardError=true};
        using(var process=Process.Start(start)){string stdout=process.StandardOutput.ReadToEnd(),stderr=process.StandardError.ReadToEnd();if(!process.WaitForExit(20000)){process.Kill();throw new Exception("Production clipboard probe timed out");}File.WriteAllText(Path.Combine(Environment.GetEnvironmentVariable("REVIEW_OUTPUT"),"clipboard-release-"+mode+".log"),stdout+stderr);return process.ExitCode;}
    }
    sealed class ClipboardSnapshot:IDisposable {
        readonly DataObject data=new DataObject();readonly List<IDisposable> resources=new List<IDisposable>();bool empty=true,written;uint sequence;
        internal ClipboardSnapshot(){var old=Clipboard.GetDataObject();if(old==null)return;foreach(string format in old.GetFormats(false)){object value=old.GetData(format,false);if(value==null)continue;object frozen;if(value is string)frozen=value;else if(value is string[])frozen=((string[])value).Clone();else if(value is byte[])frozen=((byte[])value).Clone();else if(value is MemoryStream){var stream=new MemoryStream(((MemoryStream)value).ToArray());frozen=stream;resources.Add(stream);}else if(value is Image){var image=(Image)((Image)value).Clone();frozen=image;resources.Add(image);}else throw new Exception("Cannot safely preserve clipboard format; no write performed: "+format);data.SetData(format,false,frozen);empty=false;}}
        internal void Track(){written=true;sequence=GetClipboardSequenceNumber();}
        public void Dispose(){if(written){if(GetClipboardSequenceNumber()!=sequence)Console.WriteLine("CLIPBOARD: newer external content preserved");else{if(empty)Clipboard.Clear();else Clipboard.SetDataObject(data,true,5,40);Console.WriteLine("CLIPBOARD: original contents restored; no original contents logged");}}foreach(var r in resources)r.Dispose();}
    }
    [STAThread]static int Main(){try{
        Application.EnableVisualStyles();Ui.SetDarkMode(true,false);UiMotion.SetEnabled(true);
        var sample=Examples.Parity();sample.Nodes.First(n=>n.Id=="check").TrueLabel="Positivo";sample.Nodes.First(n=>n.Id=="check").FalseLabel="Negativo";sample.Nodes.First(n=>n.Id=="check").TrueColor="#35A96C";sample.Nodes.First(n=>n.Id=="check").FalseColor="#DD5C79";sample.Nodes.First(n=>n.Id=="input").Prompt="Caffè € 👩‍💻\nQuale numero scegli?";
        var ids=new[]{"input","check","even","odd"};
        var fragment=new Diagram{Nodes=sample.Nodes.Where(n=>ids.Contains(n.Id)).ToList(),Edges=sample.Edges.Where(e=>ids.Contains(e.From)&&ids.Contains(e.To)).ToList()};
        byte[] encoded=FlowClipboard.Encode(fragment);Check(Json(FlowClipboard.Decode(encoded))==Json(fragment),"Bounded byte packet preserves every model field and order");
        Bad(new byte[0],"Empty clipboard bytes are rejected");Bad(new byte[20],"Unknown clipboard header is rejected");Bad(encoded.Take(17).ToArray(),"Truncated clipboard packet is rejected");Bad(new byte[DiagramIO.MaxFileBytes+40],"Oversized packet is rejected before parsing");var invalid=(byte[])encoded.Clone();invalid[9]=255;invalid[10]=255;invalid[11]=255;invalid[12]=127;Bad(invalid,"Oversized declared length is rejected before allocating JSON");
        using(var savedClipboard=new ClipboardSnapshot())using(var form=new MainForm(null,true)){
            form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-2800,-2200);form.Size=new Size(1180,820);form.Show();Pump(330);form.EnterEditor();Pump(330);form.SetDocument(sample,null,false);form.SingleStep();form.SingleStep();
            form.Canvas.SelectNodes(ids);form.Canvas.Focus();Pump(50);string source=Json(form.Document);var runner=form.Runner;int undo=UndoCount(form);
            Check(Key(form,Keys.Control|Keys.C),"Ctrl+C is handled by the real main form");savedClipboard.Track();var copied=FlowClipboard.Read();
            Check(copied!=null&&copied.Nodes.Count==4&&copied.Edges.Count==3,"Real Windows clipboard carries the selected group and internal edges only");
            Check(Clipboard.GetText(TextDataFormat.UnicodeText)==String.Join(Environment.NewLine,fragment.Nodes.Select(n=>n.Text)),"Native Unicode text accompanies copied blocks for ordinary text fields");
            Check(Json(form.Document)==source&&ReferenceEquals(form.Runner,runner)&&UndoCount(form)==undo,"Copy preserves source graph, execution and history");
            Check(copied.Nodes.First(n=>n.Kind==NodeKind.Decision).GetBranchLabel("true")=="Positivo"&&copied.Nodes.First(n=>n.Kind==NodeKind.Decision).TrueColor=="#35A96C"&&copied.Nodes.First(n=>n.Kind==NodeKind.Input).Prompt.Contains("Caffè"),"Native clipboard preserves decision labels/colors, input questions and Unicode");
            form.SetDocument(DiagramIO.CreateBlank(),null,false);var original=DiagramIO.Clone(form.Document);var originalIds=new HashSet<string>(original.Nodes.Select(n=>n.Id));var originalEdgeIds=new HashSet<string>(original.Edges.Select(n=>n.Id));form.Canvas.Focus();Key(form,Keys.Control|Keys.V);
            var pasted=form.Document.Nodes.Where(n=>!originalIds.Contains(n.Id)).ToList();var newIds=new HashSet<string>(pasted.Select(n=>n.Id));
            Check(pasted.Count==4&&form.Canvas.SelectionCount==4&&form.Document.Edges.Count==4,"Ctrl+V pastes and selects the whole group in another project");
            Check(!pasted.Any(n=>ids.Contains(n.Id))&&form.Document.Edges.Where(e=>!originalEdgeIds.Contains(e.Id)).All(e=>newIds.Contains(e.From)&&newIds.Contains(e.To)),"Paste assigns fresh IDs and never reconnects to source or target nodes");
            float dx=pasted[0].X-copied.Nodes[0].X,dy=pasted[0].Y-copied.Nodes[0].Y;
            Check(pasted.Zip(copied.Nodes,(a,b)=>a.X-b.X==dx&&a.Y-b.Y==dy&&a.Text==b.Text&&a.Prompt==b.Prompt&&a.TrueLabel==b.TrueLabel&&a.FalseLabel==b.FalseLabel&&a.TrueColor==b.TrueColor&&a.FalseColor==b.FalseColor).All(x=>x),"Paste preserves relative layout and every text/branch field");
            Check(pasted.All(n=>original.Nodes.All(o=>!FlowCanvas.GetNodeBounds(n).IntersectsWith(FlowCanvas.GetNodeBounds(o))))&&original.Nodes.All(o=>form.Document.Nodes.Any(n=>n.Id==o.Id&&n.X==o.X&&n.Y==o.Y)),"Paste finds clear space without moving existing blocks");
            Check(UndoCount(form)==1,"Whole-group paste is one undo operation");Check(Field<Dictionary<string,PointF>>(form.Canvas,"settleFrom")!=null,"Paste starts the existing spring placement animation");Pump(70);Shot(form.Canvas,"clipboard-paste-intermediate");Pump(420);Check(!Field<System.Windows.Forms.Timer>(form.Canvas,"manipulationTimer").Enabled,"Paste animation settles and its timer stops");
            Key(form,Keys.Control|Keys.Z);Check(Json(form.Document)==Json(original),"Ctrl+Z restores the exact graph before paste");Key(form,Keys.Control|Keys.Shift|Keys.Z);Check(form.Document.Nodes.Count==6&&form.Document.Edges.Count==4,"Ctrl+Shift+Z redoes the group paste");form.Canvas.SelectNodes(newIds);form.Canvas.Focus();Key(form,Keys.Control|Keys.X);savedClipboard.Track();
            Check(form.Document.Nodes.Count==2&&FlowClipboard.Read().Nodes.Count==4,"Ctrl+X removes the group only after native clipboard storage succeeds");Check(Field<Bitmap>(form.Canvas,"clipboardFlight")!=null,"Cut starts a real fading/lifting snapshot");Pump(70);Shot(form.Canvas,"clipboard-cut-intermediate");Pump(380);Check(Field<Bitmap>(form.Canvas,"clipboardFlight")==null&&!Field<System.Windows.Forms.Timer>(form.Canvas,"manipulationTimer").Enabled,"Cut animation releases its bitmap and timer");
            Key(form,Keys.Control|Keys.Z);Check(form.Document.Nodes.Count==6&&form.Document.Edges.Count==4,"One Ctrl+Z restores all cut nodes and incident edges");Key(form,Keys.Control|Keys.Y);Check(form.Document.Nodes.Count==2,"Ctrl+Y redoes the whole cut");Key(form,Keys.Control|Keys.V);var firstPaste=new HashSet<string>(form.Canvas.SelectedNodeIds);Key(form,Keys.Control|Keys.V);Check(form.Document.Nodes.Count==10&&!form.Canvas.SelectedNodeIds.Any(firstPaste.Contains)&&form.Document.Nodes.Select(n=>n.Id).Distinct().Count()==10,"Repeated paste makes independent selections with unique IDs");
            Key(form,Keys.Control|Keys.A);Check(form.Canvas.SelectionCount==form.Document.Nodes.Count,"Ctrl+A selects every block on the sheet");int beforeDuplicate=form.Document.Nodes.Count;Key(form,Keys.Control|Keys.D);Check(form.Document.Nodes.Count==beforeDuplicate*2,"Ctrl+D retains its established duplicate behavior");Key(form,Keys.Control|Keys.Z);Check(form.Document.Nodes.Count==beforeDuplicate,"Ctrl+Z reverses the duplicate in one action");
            form.SetDocument(Examples.Parity(),null,false);Field<SidebarTabs>(form,"tabs").SelectedTab=Field<Panel>(form,"blockTab");Pump(330);form.Canvas.SelectNode("input");Field<TextBox>(form,"expression").Text="renamed";Field<TextBox>(form,"prompt").Text="Domanda ancora nell'ispettore";form.Canvas.Focus();Key(form,Keys.Control|Keys.C);savedClipboard.Track();copied=FlowClipboard.Read();Check(copied.Nodes.Single().Text=="renamed"&&copied.Nodes.Single().Prompt=="Domanda ancora nell'ispettore","Copy includes the latest inspector draft without stale model text");
            var box=Field<TextBox>(form,"expression");box.Focus();box.SelectAll();Pump(30);Check(box.Visible&&box.Focused,"Text shortcut test operates on the visible focused native editor");string graphBeforeText=Json(form.Document);Check(!Key(form,Keys.Control|Keys.V),"Main form leaves Ctrl+V to a focused native text field");box.Paste();Check(box.Text=="renamed"&&Json(form.Document)==graphBeforeText,"Native text paste edits text without inserting diagram blocks");
            box.Text="α Caffè €";box.SelectAll();Check(!Key(form,Keys.Control|Keys.C),"Main form leaves Ctrl+C to focused text");box.Copy();savedClipboard.Track();Check(Clipboard.GetText()=="α Caffè €","Native text copy uses the actual Windows clipboard");Check(!Key(form,Keys.Control|Keys.X)&&!Key(form,Keys.Control|Keys.A)&&!Key(form,Keys.Control|Keys.Z),"Text cut, selection and undo are not hijacked by diagram commands");box.Cut();savedClipboard.Track();Check(box.Text==""&&Json(form.Document)==graphBeforeText,"Native text cut preserves the diagram");box.Undo();Check(box.Text=="α Caffè €","Native text undo still works");
            form.SetDocument(Examples.Parity(),null,false);form.Canvas.SelectNode("check");form.Canvas.Focus();string before=Json(form.Document);int history=UndoCount(form);var nativeWrite=form.Canvas.ClipboardWrite;form.Canvas.ClipboardWrite=d=>{throw new ExternalException("Simulated clipboard contention");};Key(form,Keys.Control|Keys.X);Check(Json(form.Document)==before&&UndoCount(form)==history,"Failed clipboard write never cuts nodes or adds history");form.Canvas.ClipboardWrite=nativeWrite;
            var nativeRead=form.Canvas.ClipboardRead;form.Canvas.ClipboardRead=()=>{throw new ExternalException("Simulated clipboard contention");};Key(form,Keys.Control|Keys.V);Check(Json(form.Document)==before&&UndoCount(form)==history,"Busy clipboard read cannot partly paste or mutate history");form.Canvas.ClipboardRead=nativeRead;
            Clipboard.SetText("ordinary text");savedClipboard.Track();Key(form,Keys.Control|Keys.V);Check(Json(form.Document)==before&&UndoCount(form)==history,"Ordinary clipboard text never creates unintended diagram blocks");
            using(var stream=new MemoryStream(new byte[20])){var data=new DataObject();data.SetData(FlowClipboard.Format,false,stream);Clipboard.SetDataObject(data,true,5,40);}savedClipboard.Track();Key(form,Keys.Control|Keys.V);Check(Json(form.Document)==before&&UndoCount(form)==history,"Malformed native clipboard bytes are rejected without mutation");
            FlowClipboard.Write(fragment);savedClipboard.Track();var full=DiagramIO.CreateBlank();for(int i=full.Nodes.Count;i<499;i++)full.Nodes.Add(new FlowNode{Id="full"+i,Kind=NodeKind.Process,Text="x=0",X=i*24,Y=600});form.SetDocument(full,null,false);form.Canvas.Focus();before=Json(form.Document);Key(form,Keys.Control|Keys.V);Check(Json(form.Document)==before&&UndoCount(form)==0,"Node capacity is checked before paste and history mutation");
            var edgeFull=DiagramIO.CreateBlank();for(int i=edgeFull.Edges.Count;i<1499;i++)edgeFull.Edges.Add(new FlowEdge{From=edgeFull.Nodes[0].Id,To=edgeFull.Nodes[1].Id});form.SetDocument(edgeFull,null,false);form.Canvas.Focus();before=Json(form.Document);Key(form,Keys.Control|Keys.V);Check(Json(form.Document)==before&&UndoCount(form)==0,"Edge capacity is checked before paste and history mutation");
            form.SetDocument(DiagramIO.CreateBlank(),null,false);form.Canvas.ViewOnly=true;before=Json(form.Document);uint sequence=GetClipboardSequenceNumber();Key(form,Keys.Control|Keys.X);Key(form,Keys.Control|Keys.V);Check(Json(form.Document)==before&&GetClipboardSequenceNumber()==sequence,"Read-only simulation protects graph and clipboard from cut/paste");form.Canvas.ViewOnly=false;
            typeof(FlowCanvas).GetField("_panning",F).SetValue(form.Canvas,true);Key(form,Keys.Control|Keys.V);Check(Json(form.Document)==before,"Active pointer gesture blocks clipboard shortcuts");typeof(FlowCanvas).GetField("_panning",F).SetValue(form.Canvas,false);
            form.Canvas.Focus();Key(form,Keys.Shift|Keys.Insert);Check(form.Document.Nodes.Count==6,"Shift+Insert pastes the group");Key(form,Keys.Control|Keys.Insert);savedClipboard.Track();Check(FlowClipboard.Read().Nodes.Count==4,"Ctrl+Insert copies the selection");Key(form,Keys.Shift|Keys.Delete);savedClipboard.Track();Check(form.Document.Nodes.Count==2,"Shift+Delete cuts the selection");
            UiMotion.SetEnabled(false);form.Canvas.PasteSelection();form.Canvas.CopySelection(true);savedClipboard.Track();Check(Field<Bitmap>(form.Canvas,"clipboardFlight")==null,"Reduced motion skips the cut flight");UiMotion.SetEnabled(true);
            form.SetDocument(DiagramIO.CreateBlank(),null,false);Call(form.Canvas,"EnsureContextMenu");Call(form.Canvas,"ConfigureContextMenu",new Point(4,4));Check(Field<ToolStripMenuItem>(form.Canvas,"_menuPaste").Enabled,"Context menu offers the available clipboard paste");Field<ToolStripMenuItem>(form.Canvas,"_menuPaste").PerformClick();Check(form.Document.Nodes.Count==6,"Context-menu Paste executes the same real group insertion");
            form.SetDocument(DiagramIO.CreateBlank(),null,false);form.Close();Pump(380);
            using(var tutor=new TutorDialog(new TutorStore(),new LearningStore())){
                tutor.ShowInTaskbar=false;tutor.StartPosition=FormStartPosition.Manual;tutor.Location=new Point(-2800,-2200);tutor.Show();Pump(330);tutor.OpenLesson("b02");Field<FlowButton>(tutor,"primary").PerformClick();Pump(330);Call(tutor,"ReleasePage");tutor.Current.Drafts.Clear();tutor.Current.Document=Tutor.Lessons.First(l=>l.id=="b02").Solution();Call(tutor,"RenderWorkspace");Pump(330);tutor.Canvas.SelectNode("messaggio");Field<TextBox>(tutor,"expression").Text="\"Bozza copiata\"";tutor.Canvas.Focus();Key(tutor,Keys.Control|Keys.C);savedClipboard.Track();Check(FlowClipboard.Read().Nodes.Single().Text=="\"Bozza copiata\"","Lesson copy includes the learner's latest unapplied draft");int count=tutor.Current.Document.Nodes.Count;Key(tutor,Keys.Control|Keys.V);Check(tutor.Current.Document.Nodes.Count==count+1,"Ctrl+V works in the lesson editing canvas");Key(tutor,Keys.Control|Keys.Z);Check(tutor.Current.Document.Nodes.Count==count,"Ctrl+Z undoes lesson paste");Key(tutor,Keys.Control|Keys.Y);Check(tutor.Current.Document.Nodes.Count==count+1,"Ctrl+Y redoes lesson paste");tutor.ShowOverview();tutor.Close();Pump(380);
            }
            string sourceFile=Path.Combine(Environment.GetEnvironmentVariable("REVIEW_OUTPUT"),"clipboard-source.frociart");DiagramIO.Save(sourceFile,sample);
            Check(ReleaseProbe(Environment.GetEnvironmentVariable("BASELINE_EXE"),sourceFile,"baseline")==0,"Actual previous EXE confirms the missing diagram copy shortcut");
            int copyExit=ReleaseProbe(Environment.GetEnvironmentVariable("PRODUCTION_EXE"),sourceFile,"copy");savedClipboard.Track();Check(copyExit==0,"Actual final EXE copies before its process exits");
            Check(ReleaseProbe(Environment.GetEnvironmentVariable("PRODUCTION_EXE"),sourceFile,"paste")==0,"A second final EXE process pastes, undoes and redoes the clipboard group");
        }
        Check(FlowTransitions.Active==0&&PopupGhost.ActiveCount==0,"Closing releases all native transition overlays");
        Console.WriteLine("CLIPBOARD_SHORTCUTS_PASS checks="+checks+"; real Windows clipboard, real native controls, injected busy faults; external hardware keyboard NOT_RUN");return 0;
    }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
